supp+=p('Save this public supplement page as HTML. Save the following original standard-library recovery program as <code>recover-archive.py</code>, then run <code>python3 -I recover-archive.py supplement.html</code>. It verifies the checksum and ZIP integrity and writes <code>fracture-atlas-recovered.zip</code>. It performs no network access and does not extract or execute the contents. Open the recovered <code>index.html</code> after extraction to use the explorer locally.')+code((root/'recover-archive.py').read_text())
supp+='<!-- wp:details -->\n<details class="wp-block-details"><summary>Complete data/source ZIP as Base64 (large; expand to copy)</summary>\n'+code(encoded)+'</details>\n<!-- /wp:details -->\n'
